17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.slf4j.Logger;
23	import org.slf4j.LoggerFactory;
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.samples.petclinic.service.IdempotencyKeyRegistry;
42	import org.springframework.samples.petclinic.util.AddressValidator;
43	import org.springframework.samples.petclinic.util.DisposableEmailValidator;
44	import org.springframework.samples.petclinic.util.PostcodeValidator;
45	import org.springframework.samples.petclinic.util.RegistrationDateValidator;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    private final IdempotencyKeyRegistry idempotencyKeyRegistry;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper,
79	                                 IdempotencyKeyRegistry idempotencyKeyRegistry) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	        this.idempotencyKeyRegistry = idempotencyKeyRegistry;
85	    }
86	
87	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
88	    @Override
89	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
90	        Collection<Owner> owners;
91	        if (lastName != null) {
92	            owners = this.clinicService.findOwnerByLastName(lastName);
93	        } else {
94	            owners = this.clinicService.findAllOwners();
95	        }
96	        if (owners.isEmpty()) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
105	        Owner owner = this.clinicService.findOwnerById(ownerId);
106	        if (owner == null) {
107	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
108	        }
109	        return new ResponseEntity<>(toOwnerDtoWithWarning(owner), HttpStatus.OK);
110	    }
111	
112	    /** Map an owner to its DTO, setting the read-only {@code bulkSignupWarning} flag the same way
113	     *  for every owner response. */
114	    private OwnerDto toOwnerDtoWithWarning(Owner owner) {
115	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
116	        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupDay());
117	        return ownerDto;
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
123	        // A create retried with an already-seen idempotency key returns the originally created
124	        // owner with 200, rather than creating a duplicate.
125	        Integer existingId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey).orElse(null);
126	        if (existingId != null) {
127	            Owner existing = this.clinicService.findOwnerById(existingId);
128	            if (existing != null) {
129	                return new ResponseEntity<>(toOwnerDtoWithWarning(existing), HttpStatus.OK);
130	            }
131	        }
132	        HttpHeaders headers = new HttpHeaders();
133	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
134	        AddressValidator.validate(owner.getAddress());
135	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
136	        DisposableEmailValidator.validate(owner.getEmail());
137	        RegistrationDateValidator.validate(owner.getRegistrationDate());
138	        if (this.clinicService.isDailyRegistrationAtCapacity()) {
139	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
140	        }
141	        // The household id is deterministic from (lastName, postcode), so owners sharing a last name
142	        // and postcode are automatically the same household. It no longer gates duplicate detection
143	        // (that is the identity key alone) but still drives household-derived fields.
144	        owner.setHouseholdId(this.clinicService.householdIdFor(owner.getLastName(), owner.getPostcode()));
145	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
146	        // Duplicate detection is the single identity key: reject only when the new owner's whole
147	        // identity key (SHA-256 over normalizedTelephone|lowerEmail|soundex(lastName)) matches an
148	        // existing, non-deleted owner's. Two owners with the same last name and postcode but different
149	        // telephones have distinct keys and are created as a soft match rather than rejected.
150	        if (this.clinicService.isIdentityKeyInUse(owner)) {
151	            return new ResponseEntity<>(HttpStatus.CONFLICT);
152	        }
153	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
154	            return new ResponseEntity<>(HttpStatus.CONFLICT);
155	        }
156	        this.clinicService.saveOwner(owner, sharesHousehold);
157	        this.idempotencyKeyRegistry.remember(idempotencyKey, owner.getId());
158	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
159	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
160	            ownerMapper.formatMembershipLevel(owner), ownerMapper.formatMembershipNumber(owner));
161	        OwnerDto ownerDto = toOwnerDtoWithWarning(owner);
162	        headers.setLocation(UriComponentsBuilder.newInstance()
163	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
164	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
170	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
171	        if (currentOwner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        PostcodeValidator.validate(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
175	        DisposableEmailValidator.validate(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
176	        ownerMapper.applyAddressFields(ownerFieldsDto, currentOwner);
177	        AddressValidator.validate(currentOwner.getAddress());
178	        currentOwner.setCity(ownerFieldsDto.getCity());
179	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
180	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
181	        currentOwner.setLastName(ownerFieldsDto.getLastName());
182	        currentOwner.setTitle(ownerMapper.mapTitle(ownerFieldsDto.getTitle()));
183	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
184	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
185	        this.clinicService.saveOwner(currentOwner);
186	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Transactional
191	    @Override
192	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
193	        Owner owner = this.clinicService.findOwnerById(ownerId);
194	        if (owner == null) {
195	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
196	        }
197	        this.clinicService.deleteOwner(owner);
198	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
199	    }
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
204	        Owner owner = this.clinicService.findOwnerById(ownerId);
205	        if (owner == null) {
206	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
207	        }
208	        HttpHeaders headers = new HttpHeaders();
209	        Pet pet = petMapper.toPet(petFieldsDto);
210	        owner.setId(ownerId);
211	        pet.setOwner(owner);
212	        pet.getType().setName(null);
213	        this.clinicService.savePet(pet);
214	        PetDto petDto = petMapper.toPetDto(pet);
215	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
216	            .buildAndExpand(pet.getId()).toUri());
217	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
223	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
224	        if (currentOwner != null) {
225	            Pet currentPet = this.clinicService.findPetById(petId);
226	            if (currentPet != null) {
227	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
228	                currentPet.setName(petFieldsDto.getName());
229	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
230	                this.clinicService.savePet(currentPet);
231	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
232	            }
233	        }
234	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
235	    }
236	
237	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
238	    @Override
239	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
240	        HttpHeaders headers = new HttpHeaders();
241	        Visit visit = visitMapper.toVisit(visitFieldsDto);
242	        Pet pet = new Pet();
243	        pet.setId(petId);
244	        visit.setPet(pet);
245	        this.clinicService.saveVisit(visit);
246	        VisitDto visitDto = visitMapper.toVisitDto(visit);
247	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
248	            .buildAndExpand(visit.getId()).toUri());
249	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
250	    }
251	
252	
253	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
254	    @Override
255	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
256	        Owner owner = this.clinicService.findOwnerById(ownerId);
257	        if (owner != null) {
258	            Pet pet = owner.getPet(petId);
259	            if (pet != null) {
260	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
261	            }
262	        }
263	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
264	    }
265	}
